import { render, screen, fireEvent } from '@testing-library/react';
import { AIKeyDialog } from './ai-key-dialog';

describe('AIKeyDialog responsive & key handling', () => {
  it('verifies input lacks Enter key submission handler', () => {
    const onOpenChange = jest.fn();
    render(<AIKeyDialog open={true} onOpenChange={onOpenChange} />);
    const input = screen.getByPlaceholderText(/AIzaSy/i);
    fireEvent.change(input, { target: { value: 'AIzaSyValidMockKey123' } });
    fireEvent.keyDown(input, { key: 'Enter', code: 'Enter' });
    // Enter key has no effect because there is no form submission or onKeyDown handler
    expect(onOpenChange).not.toHaveBeenCalled();
  });

  it('verifies DialogFooter forces flex-row without wrapping', () => {
    const { container } = render(<AIKeyDialog open={true} onOpenChange={jest.fn()} />);
    const footer = container.querySelector('[class*="flex-row"]');
    expect(footer?.className).toContain('flex-row');
    expect(footer?.className).not.toContain('flex-wrap');
    expect(footer?.className).not.toContain('flex-col');
  });
});
